/* ================= ADDITIONS TO EXISTING PRESENTATIONS ================= */
/* stroke: glucose first */
add("weak",[Q("gluc","Has anyone checked a capillary glucose yet?","Hypoglycaemia is the commonest and most quickly reversible stroke mimic and can cause a focal deficit, including hemiparesis; it is tested in a minute.","Check glucose before anything else; NICE asks you to exclude hypoglycaemia in every sudden neurological deficit. A normal glucose with a sudden deficit means the stroke pathway now.","Hypoglycaemia (stroke mimic)","NICE NG128 stroke 2019, updated 2022 (recommendation 1.1.2)")],0);
P("weak").now=["Capillary glucose first","Any sudden deficit: stroke call and imaging now; thrombolysis to 4.5 h, thrombectomy for large-vessel occlusion to 24 h","New saddle or bladder symptoms with leg weakness: emergency MRI, do not wait for retention"];
/* trauma: tetanus, time, mechanisms */
add("trauma",[
 Q("time","What time did it happen?","Time since injury dates the wound (closing and antibiotic decisions), the window for tranexamic acid in major bleeding (within 3 hours), and how long the patient has been compensating.","Major bleeding within 3 hours of injury means tranexamic acid per protocol; an old wound may be left open.","Timing of interventions","CRASH-2 collaborators 2011, Lancet (tranexamic acid within 3 hours); ATLS 11th ed 2025"),
 Q("tet","When was your last tetanus injection, and did you complete the course as a child?","Tetanus-prone wounds (soil, manure, puncture, burns, devitalised tissue, delay over 6 hours) in someone without a complete course can cause tetanus, which is still seen in workers.","Incomplete or unknown immunisation with a tetanus-prone wound means a booster and, for high-risk wounds, human tetanus immunoglobulin.","Tetanus","UKHSA Green Book ch. 30 (tetanus); ATLS 11th ed (wound care)"),
 Q("mech2","Was there a fire, an explosion, electricity, a chemical or a crush, and for how long were you trapped?","Burns and smoke bring airway and carbon monoxide or cyanide risks; blast injures air-filled organs; electrical injury damages deep tissue and the heart beyond what the skin shows; prolonged crush releases potassium and myoglobin when freed.","Each mechanism adds a specific check: airway and carboxyhaemoglobin (fire), ECG and CK (electrical), chest and abdomen imaging (blast), and potassium, ECG and fluids (crush).","Hidden injuries by mechanism","ATLS 11th ed 2025; Parkland formula for burns (tools)")]);
P("trauma").now=["x first: stop exsanguinating external bleeding (pressure, tourniquet, packing) before the airway","Then ABCDE with C-spine care","Tranexamic acid within 3 hours for major bleeding","Pregnancy test in women of reproductive age","Tetanus status for every wound"];
/* syncope: haemorrhage and heat */
add("sync",[
 Q("bleed","Any bleeding, black stools, a missed period, or pain in the back or tummy?","Syncope from hidden haemorrhage (ruptured ectopic pregnancy, GI bleed, leaking aortic aneurysm) is the collapse that kills young women and older men; the bleeding may not be visible yet.","Any of these means a pregnancy test in women, a rectal examination or stool check, a bedside ultrasound of the aorta in older men, and a haemoglobin and lactate.","Haemorrhage","ESC syncope guideline 2018 (initial evaluation); Crochet 2013, JAMA RCE (ectopic)"),
 Q("heat","Did it happen in the heat, after standing or working outside, and have you been drinking enough?","Heat syncope is pooling in dilated skin vessels in the unacclimatised; confusion or a high core temperature makes it heat stroke instead.","Heat syncope means shade, lying flat and fluids; any confusion means a rectal temperature and the heat illness pathway.","Heat syncope","Roberts 2023, ACSM consensus on exertional heat illness")]);
/* abdo: torsion, sickle cell, DKA */
add("abdo",[
 Q("testis","In a boy or young man: any pain or swelling in the testicles, now or before?","Testicular torsion often presents as lower abdominal pain and vomiting, and teenagers may not mention the scrotum. Salvage falls steeply after about 6 hours.","Testicular pain means examining the scrotum now and urgent urology; do not wait for an ultrasound when torsion is likely.","Testicular torsion","Barbosa 2013, J Urol (TWIST score); EAU paediatric urology guideline 2023"),
 Q("scd","Do you have sickle cell disease, and is this like your usual crisis?","Abdominal vaso-occlusive crises, splenic sequestration, gallstones and girdle syndrome all occur in sickle cell disease, which is common in parts of Saudi Arabia (the Eastern and south-western regions).","A sickle crisis means prompt analgesia within 30 minutes, oxygen if hypoxic and fluids; a falling haemoglobin with a large spleen means sequestration.","Sickle cell crisis","NICE CG143 sickle cell acute painful episode 2012; Jastaniah 2011, Ann Saudi Med (sickle cell disease in Saudi Arabia)"),
 Q("dka","Are you diabetic, thirsty, passing a lot of urine, or breathing fast?","Diabetic ketoacidosis causes abdominal pain and vomiting that mimic a surgical abdomen and resolve with treatment.","Check a capillary glucose and ketones in every acute abdomen with vomiting.","Diabetic ketoacidosis","JBDS DKA guideline 2023")]);
addTo("abdo","dd",["Testicular torsion","Sickle cell crisis"]);
/* red eye: arc eye and chemicals */
add("redeye",[
 Q("arc","Have you been welding, or near welding, without a shield, and did both eyes become painful 6 to 12 hours later?","Ultraviolet from the arc burns the corneal epithelium (photokeratitis); pain, watering and photophobia start hours later, often waking the worker at night.","Bilateral pain hours after welding means fluorescein, cycloplegic and analgesia (not repeated topical anaesthetic), and a check that welding screens and filters are used.","Arc eye (photokeratitis)","Kanski's Clinical Ophthalmology, 9th ed; HSE guidance on welding"),
 Q("chem","Did a chemical splash into the eye, and was it an alkali (cement, lime, oven cleaner) or acid?","Alkalis penetrate the cornea and keep damaging it; irrigation within seconds decides the outcome.","Any chemical splash means immediate irrigation with litres of saline or water until the pH is neutral, before history or examination.","Chemical eye injury","Kanski's Clinical Ophthalmology, 9th ed (chemical injury: irrigate first)")]);
addTo("redeye","dd",["Arc eye (photokeratitis)","Chemical injury"]);
/* fever: Saudi endemic infections */
add("fever",[
 Q("ksa","Where do you live and work: any contact with camels, goats or sheep, raw (unpasteurised) milk or cheese, Hajj or Umrah, or mosquito bites in Jeddah or Jazan?","Brucellosis from raw camel, goat or sheep milk is a classic cause of prolonged fever in Saudi Arabia, with sweats, back and joint pain; MERS-CoV follows contact with camels or with infected patients; dengue is endemic in the western and south-western regions; Hajj and Umrah bring meningococcal and respiratory infections.","Raw milk or livestock contact means brucella serology and blood cultures (warn the laboratory: brucella is a laboratory hazard); camel or healthcare contact with fever and cough means isolation and MERS-CoV testing; mosquito exposure means dengue testing and caution with NSAIDs.","Brucellosis, MERS-CoV, dengue","Saudi MOH MERS-CoV case definition and guidelines; Pappas 2005, NEJM (brucellosis); Memish 2014, Lancet (Hajj: infectious disease surveillance and control)"),
 Q("scd","Do you have sickle cell disease or G6PD deficiency, or have you had your spleen removed?","Sickle cell disease causes functional asplenia and a high risk of pneumococcal sepsis; fever in sickle cell disease is an emergency. G6PD deficiency (common in the Gulf) means some antimalarials and other oxidant drugs cause haemolysis.","Fever with sickle cell disease means cultures and antibiotics within the hour; check G6PD before primaquine or dapsone.","Sepsis in hyposplenism","NICE CG143 2012; WHO malaria guidelines (G6PD testing before primaquine)")]);
addTo("fever","dd",["Brucellosis","MERS-CoV","Dengue","Sickle cell crisis or sepsis in hyposplenism"]);
addTo("fever","red",["Camel or healthcare contact with fever and cough: isolate and test for MERS-CoV","Fever in sickle cell disease"]);
/* cough: MERS */
add("cough",[Q("mers","In the last 14 days, have you had contact with camels or camel milk, or with a patient with a severe chest infection in a hospital?","MERS-CoV is a zoonosis from dromedary camels with spread in health care settings; the incubation period is up to about 14 days, and most cases have been reported from Saudi Arabia.","A positive answer with fever and cough means standard, contact and airborne precautions now, MERS-CoV testing and notification per the Saudi MOH guideline.","MERS-CoV","Saudi MOH MERS-CoV guidelines for health care professionals; WHO MERS-CoV fact sheet")]);
addTo("cough","dd",["MERS-CoV"]);
/* joint: brucellosis and sickle cell */
add("joint",[
 Q("brucella","Have you drunk raw camel, goat or sheep milk or eaten fresh unpasteurised cheese, and have you had fevers and night sweats with the joint pain?","Brucellosis commonly causes a sacroiliitis or large-joint monoarthritis, and spondylitis in older patients, with undulant fever and sweats.","Raw milk exposure with joint pain means brucella serology and blood cultures; treat for weeks with combination therapy.","Brucella arthritis","Pappas 2005, NEJM (brucellosis)"),
 Q("scd","Do you have sickle cell disease, and is the bone or joint pain like your usual crisis, or different, with fever and one hot area?","Bone infarction and osteomyelitis (including Salmonella) look alike in sickle cell disease; a single hot, swollen joint may be septic.","A different pain with fever and a single focus means imaging, cultures and aspiration if a joint is involved.","Sickle cell bone crisis or osteomyelitis","NICE CG143 2012")]);
addTo("joint","dd",["Brucellosis","Sickle cell bone crisis or osteomyelitis"]);
/* chest: sickle cell acute chest syndrome */
add("chest",[Q("scd","Do you have sickle cell disease, and do you have fever, cough or breathlessness with the pain?","Acute chest syndrome (new infiltrate with chest pain, fever, hypoxia or respiratory symptoms) is a leading cause of death in sickle cell disease.","Chest pain with fever or hypoxia in sickle cell disease means a chest X-ray, oxygen, antibiotics and early haematology input; exchange transfusion may be needed.","Acute chest syndrome","Howard 2015, Br J Haematol (BSH acute chest syndrome guideline)")]);
/* occupational history: heat question and links */
add("occ",[Q("heat","Do you work outdoors or in a hot workshop in summer, and what does the employer provide: shade, water, rest breaks, shift times?","Heat is the commonest physical hazard on Gulf construction sites. In Saudi Arabia outdoor work in direct sun is banned from 12:00 to 15:00 between 15 June and 15 September.","Outdoor work in summer means asking about heat illness symptoms and checking the heat plan; see the heat illness presentation.","Heat illness","Saudi MHRSD midday outdoor work ban; Roberts 2023, ACSM consensus")]);
